function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbget($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>45]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$http>=200&&$http<300,'data'=>is_array($d)?$d:[],'body'=>$b];}
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
?><!doctype html><html><head><title>Morning Brief</title><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:#f5f3ef;font-family:Arial;color:#111}.hero{background:#111827;color:white;padding:30px}.hero h1{color:#c8a96e}.wrap{max-width:1200px;margin:auto;padding:20px}.panel{background:white;border-radius:18px;padding:20px;margin:16px 0}.btn{background:#c8a96e;padding:10px 14px;border-radius:10px;font-weight:900;text-decoration:none;color:#111}pre{white-space:pre-wrap;background:#111827;color:white;padding:16px;border-radius:12px}</style></head><body><?php $rows=sbget('jessica_briefs?select=*&order=created_at.desc&limit=20'); ?><section class='hero'><h1>Jessica Morning Brief</h1><p>Daily Hunter, Lead, Content, and Action summary.</p></section><main class='wrap'><p><a class='btn' target='_blank' href='/lead-engine/build-morning-brief.php?key=<?=h($key)?>'>Build New Brief</a></p><?php foreach($rows['data'] as $b):?><section class='panel'><h2><?=h($b['title'])?></h2><pre><?=h($b['summary'])?></pre></section><?php endforeach;?></main></body></html>